import re

def solve(env, goal):
    def parse_goal(g):
        g = g.lower()
        m = re.search(r'put\s+(.+?)\s+(?:in|into|on|to)\s+(.+?)(?:\.|$)', g)
        if m:
            return m.group(1).strip(), m.group(2).strip()
        return None, None

    def find_objects(text):
        # find object names in an observation like "you see a X, and a Y"
        return re.findall(r'\b([a-z]+(?:\s+\d+)?)\b', text)

    def clean_obj(o):
        return re.sub(r'\s+\d+$', '', o).strip()

    def count_needed(phrase):
        # "two spraybottle" -> (2, "spraybottle")
        m = re.match(r'(one|two|three|four|five|six|seven|eight|nine|ten)\s+(.+)', phrase)
        if m:
            nums = {'one':1,'two':2,'three':3,'four':4,'five':5,'six':6,'seven':7,'eight':8,'nine':9,'ten':10}
            return nums[m.group(1)], m.group(2).strip()
        return 1, phrase

    target_phrase, dest_phrase = parse_goal(goal)
    if target_phrase is None:
        return

    num, target = count_needed(target_phrase)
    target = clean_obj(target)
    dest = clean_obj(dest_phrase)

    # Track delivered count
    delivered = 0
    # Parse initial room for receptacle list
    obs = env.observation
    receptacles = []
    for m in re.finditer(r'\b([a-z]+(?:\s+\d+)?)\b', obs):
        name = m.group(1)
        if re.match(r'^[a-z]+ \d+$', name):
            receptacles.append(name)

    # We'll search by going to each receptacle and looking
    visited = set()
    carrying = None
    steps = 0

    def go(name):
        nonlocal steps
        if steps >= 45:
            return None
        steps += 1
        return env.step("go to " + name)

    def look_here():
        nonlocal steps
        steps += 1
        return env.step("look")

    def take(obj):
        nonlocal steps, carrying
        steps += 1
        r = env.step("take " + obj + " from " + current_loc)
        if 'pick up' in r.lower() or 'you pick' in r.lower():
            carrying = clean_obj(obj)
        return r

    def drop():
        nonlocal steps, carrying, delivered
        if carrying is None:
            return None
        steps += 1
        r = env.step("move " + carrying + " to " + dest)
        if 'you move' in r.lower():
            carrying = None
            delivered += 1
        return r

    current_loc = None

    # First, scan receptacles for target objects
    candidates = []
    for rec in receptacles:
        if steps >= 40:
            break
        r = go(rec)
        if r is None:
            break
        current_loc = rec
        # check observation for target
        found = re.findall(r'\b' + re.escape(target) + r' \d+\b', r)
        for f in found:
            candidates.append((rec, f))

    # Also check if we're already holding something
    if steps < 45:
        steps += 1
        inv = env.step("inventory")
        held = re.findall(r'\b' + re.escape(target) + r' \d+\b', inv)
        if held:
            carrying = held[0]

    # Deliver while needed
    while delivered < num and steps < 48:
        if carrying is None:
            # pick next candidate
            picked = None
            for rec, obj in candidates:
                if steps >= 47:
                    break
                r = go(rec)
                if r is None:
                    break
                current_loc = rec
                # verify still there
                if obj in r or 'you see' in r.lower():
                    steps += 1
                    rr = env.step("take " + obj + " from " + rec)
                    if 'pick up' in rr.lower() or 'you pick' in rr.lower():
                        carrying = obj
                        candidates.remove((rec, obj))
                        picked = True
                        break
            if carrying is None:
                # look for more
                for rec in receptacles:
                    if steps >= 47:
                        break
                    r = go(rec)
                    if r is None:
                        break
                    current_loc = rec
                    found = re.findall(r'\b' + re.escape(target) + r' \d+\b', r)
                    if found:
                        obj = found[0]
                        steps += 1
                        rr = env.step("take " + obj + " from " + rec)
                        if 'pick up' in rr.lower() or 'you pick' in rr.lower():
                            carrying = obj
                            break
                if carrying is None:
                    break
        # go to dest and drop
        r = go(dest)
        if r is None:
            break
        current_loc = dest
        drop()

    # final drop if still carrying
    if carrying is not None and steps < 49:
        go(dest)
        current_loc = dest
        drop()
